    "// 1-Bit Comparator — Greater, Equal, Less",
    "//",
    "// GT = A AND (NOT B); LT = (NOT A) AND B; EQ = XNOR(A, B). Exactly one of the",
    "// three is always 1: they are mutually exclusive by construction.",
    "#include <map>",
    "#include <string>",
    "#include <vector>",
    "#include \"../sim/logic.hpp\"",
