    "    int combos[4][2] = {{0, 0}, {0, 1}, {1, 0}, {1, 1}};",
    "    std::vector<std::vector<int>> rows;",
    "    for (auto& c : combos) {",
    "        int GT = AND(c[0], NOT(c[1])), LT = AND(NOT(c[0]), c[1]), EQ = XNOR(c[0], c[1]);",
    "        rows.push_back({c[0], c[1], GT, EQ, LT});",
    "    }",
